def get_lattice_coords(latvec, nlatvec=1):
    lattice_coords = []
    for x in range(-nlatvec, nlatvec + 1):
        for y in range(-nlatvec, nlatvec + 1):
            for z in range(-nlatvec, nlatvec + 1):
                coord = latvec[0] * x + latvec[1] * y + latvec[2] * z
                if np.linalg.norm(coord) <= (2 * nlatvec + 1) / 2:
                    lattice_coords.append(np.array([x, y, z]))
    return np.array(lattice_coords)
